package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

/** A person's plan: a claim of {@code amount} on every plan date up to the end — the start then every
 * {@code every} days, or, for a monthly plan, {@code day} of every month from the start's month (the
 * month's last day when it is shorter), those before the start left out; with the plan dates it has made
 * its claim for, and the times it was paused: a plan date on or after a pause and before its resume is
 * skipped, not postponed; and the changes of its amount, oldest first: a change applies to the claims
 * generated after it, those already made keep theirs. */
@Entity
@Table(name = "person_plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(nullable = false)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    @Column(name = "every_days")
    private Integer every;

    @Column(name = "day_of_month")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_claim", joinColumns = @JoinColumn(name = "plan_id"))
    private List<PlanClaim> claims = new ArrayList<>();

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_pause", joinColumns = @JoinColumn(name = "plan_id"))
    private Set<PlanPause> pauses = new HashSet<>();

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_change", joinColumns = @JoinColumn(name = "plan_id"))
    @OrderColumn(name = "position")
    private List<PlanChange> changes = new ArrayList<>();

    protected Plan() {
    }

    /** A plan every {@code every} days (day null) or monthly on {@code day} (every null). */
    public Plan(String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    /** The interval in days; null for a monthly plan. */
    public Integer getEvery() {
        return every;
    }

    /** The day of the month (1 to 31) of a monthly plan; null for one every N days. */
    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }

    /** How many claims the plan has made so far. */
    public int getGenerated() {
        return claims.size();
    }

    /** The plan dates up to the end and {@code today} that the plan has made no claim for yet, earliest first. */
    public List<LocalDate> datesDue(LocalDate today) {
        LocalDate last = end.isBefore(today) ? end : today;
        Set<LocalDate> made = claims.stream().map(PlanClaim::getDate).collect(Collectors.toSet());
        List<LocalDate> due = new ArrayList<>();
        for (LocalDate on : dates(last)) {
            if (!made.contains(on) && !skipped(on)) due.add(on);
        }
        return due;
    }

    /** The first {@code count} plan dates after {@code today} and on or before the end, earliest first. */
    public List<LocalDate> nextDates(LocalDate today, int count) {
        return dates(end).stream().filter(on -> on.isAfter(today) && !skipped(on)).limit(count).toList();
    }

    /** The changes of the plan's amount, oldest first. */
    public List<PlanChange> getChanges() {
        return List.copyOf(changes);
    }

    /** Change the plan's amount on {@code on} to {@code to}, for the claims generated from then on;
     * refused when it is not above zero. */
    public void changeAmount(LocalDate on, BigDecimal to) {
        if (to.signum() <= 0) throw new PlanAmountException();
        amount = to;
        changes.add(new PlanChange(on, to));
    }

    /** Whether the plan is paused now: paused and not yet resumed. */
    public boolean isPaused() {
        return pauses.stream().anyMatch(PlanPause::isOpen);
    }

    /** Pause the plan from {@code on}; refused when it is already paused. */
    public void pause(LocalDate on) {
        if (isPaused()) throw new PlanPauseException();
        pauses.add(new PlanPause(on, null));
    }

    /** Resume the plan on {@code on}; refused when it is not paused. */
    public void resume(LocalDate on) {
        PlanPause open = pauses.stream().filter(PlanPause::isOpen).findFirst().orElseThrow(PlanPauseException::new);
        pauses.remove(open);
        pauses.add(new PlanPause(open.getPausedOn(), on));
    }

    /** Whether the plan date {@code on} falls in a pause, so is skipped. */
    private boolean skipped(LocalDate on) {
        return pauses.stream().anyMatch(p -> p.skips(on));
    }

    /** The plan dates up to {@code last}, earliest first. */
    private List<LocalDate> dates(LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        if (day == null) {
            for (LocalDate on = start; !on.isAfter(last); on = on.plusDays(every)) dates.add(on);
            return dates;
        }
        for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
            LocalDate on = month.atDay(Math.min(day, month.lengthOfMonth()));
            if (!on.isBefore(start) && !on.isAfter(last)) dates.add(on);
        }
        return dates;
    }

    /** Keep that the plan made its claim {@code claimId} for {@code date}. */
    public void made(LocalDate date, Long claimId) {
        claims.add(new PlanClaim(date, claimId));
    }
}
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;

/** The plans of the people on a sheet. Generating makes, for every plan on the sheet in the order they
 * were added, a DRAFT claim of the plan's amount, dated that day with an empty note, for every plan date
 * up to the plan's end and the sheet's today it has made none for yet. Each claim is added by the claim
 * form's rules, in a change of its own: a date the form refuses is skipped, writes nothing, and is tried
 * again the next time. */
@Service
public class PlanService {

    private final PlanRepository plans;
    private final PersonRepository people;
    private final SheetRepository sheetRepository;
    private final SheetService sheets;
    private final ClaimService claims;
    private final Audit audit;
    private final TransactionTemplate eachClaim;
    private final SettingsService settings;

    public PlanService(PlanRepository plans, PersonRepository people, SheetRepository sheetRepository,
            SheetService sheets, ClaimService claims, Audit audit, PlatformTransactionManager transactions,
            SettingsService settings) {
        this.plans = plans;
        this.people = people;
        this.sheetRepository = sheetRepository;
        this.sheets = sheets;
        this.claims = claims;
        this.audit = audit;
        this.settings = settings;
        this.eachClaim = new TransactionTemplate(transactions);
        this.eachClaim.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
    }

    /** The sheet's plans in the order they were added. */
    @Transactional(readOnly = true)
    public List<Plan> plans(String sheetId) {
        return plans.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** The sheet's today, which a plan's next dates are after. */
    @Transactional(readOnly = true)
    public LocalDate today(String sheetId) {
        return sheets.today(sheetId);
    }

    /** Add a plan for the person, every {@code every} days or monthly on {@code day} (exactly one given);
     * refused when the end is before the start, the interval is under 1 day, the day is not 1 to 31, both
     * or neither are given, or the amount is not above zero. Records PLAN_ADDED. */
    @Transactional
    public Plan add(String sheetId, String user, long personId, BigDecimal amount, LocalDate start, Integer every,
            Integer day, LocalDate end) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (end.isBefore(start) || amount.signum() <= 0 || (every == null) == (day == null)
                || (every != null && every < 1) || (day != null && (day < 1 || day > 31))) {
            throw new PlanDatesException();
        }
        Plan plan = plans.saveAndFlush(new Plan(sheetId, personId, amount, start, every, day, end));
        audit.change("PLAN_ADDED", sheetId, user, "name=" + person.getName(),
                "amount=" + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString(), "start=" + start,
                every != null ? "every=" + every : "day=" + day, "end=" + end);
        return plan;
    }

    /** Pause the plan from the sheet's today; refused when it is already paused. Records PLAN_PAUSED. */
    @Transactional
    public Plan pause(String sheetId, String user, long planId) {
        Plan plan = plans.findByIdAndSheetId(planId, sheetId).orElseThrow(PlanNotFoundException::new);
        plan.pause(sheets.today(sheetId));
        return changed(sheetId, user, plan, "PLAN_PAUSED");
    }

    /** Resume the plan on the sheet's today; refused when it is not paused. Records PLAN_RESUMED. */
    @Transactional
    public Plan resume(String sheetId, String user, long planId) {
        Plan plan = plans.findByIdAndSheetId(planId, sheetId).orElseThrow(PlanNotFoundException::new);
        plan.resume(sheets.today(sheetId));
        return changed(sheetId, user, plan, "PLAN_RESUMED");
    }

    /** Change the plan's amount, from the sheet's today, for the claims generated from then on; refused
     * when it is not above zero. Records PLAN_CHANGED. */
    @Transactional
    public Plan changeAmount(String sheetId, String user, long planId, BigDecimal amount) {
        Plan plan = plans.findByIdAndSheetId(planId, sheetId).orElseThrow(PlanNotFoundException::new);
        plan.changeAmount(sheets.today(sheetId), amount);
        return changed(sheetId, user, plan, "PLAN_CHANGED",
                "amount=" + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
    }

    private Plan changed(String sheetId, String user, Plan plan, String event, String... fields) {
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
        Plan saved = plans.saveAndFlush(plan);
        List<String> line = new ArrayList<>(List.of("name=" + person.getName(), "start=" + plan.getStart()));
        line.addAll(List.of(fields));
        audit.change(event, sheetId, user, line.toArray(String[]::new));
        return saved;
    }

    /** Make the claims every plan on the sheet is due, in the order the plans were added and, within a
     * plan, by date; the claims made, in the order they were made. Not one change: each claim is. */
    public List<Claim> generate(String sheetId, String user) {
        if (sheetRepository.findById(sheetId).isEmpty()) return List.of();
        if (settings.roleOf(sheetId, user) == Role.VIEWER) return List.of();
        LocalDate today = sheets.today(sheetId);
        List<Claim> made = new ArrayList<>();
        for (Plan plan : plans(sheetId)) {
            for (LocalDate date : plan.datesDue(today)) {
                try {
                    made.add(eachClaim.execute(status -> make(sheetId, user, plan.getId(), date)));
                } catch (RuntimeException refused) {
                    // The claim form refused this date: it is skipped, and tried again next time.
                }
            }
        }
        return made;
    }

    private Claim make(String sheetId, String user, long planId, LocalDate date) {
        Plan plan = plans.findByIdAndSheetId(planId, sheetId).orElseThrow(IllegalStateException::new);
        Claim claim = claims.add(sheetId, user, plan.getPersonId(), plan.getAmount(), date, "", null);
        plan.made(date, claim.getId());
        plans.saveAndFlush(plan);
        return claim;
    }
}
package net.officefloor.hq.app.plan;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.claim.ClaimService;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The plans on a sheet, and the button that generates their claims. The signed-in user's name travels in
 * the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/plans")
@Validated
public class PlanController {

    /** A plan: its id, its person, its amount (as text with two decimals), start, interval in days (null
     * for a monthly plan), day of the month (null for one every N days), end, and how many claims it has
     * made so far, and its next dates: the first five plan dates after the sheet's today and on or before
     * the end and not skipped by a pause, comma and space separated (empty when there are none), and
     * whether it is paused now, and the changes of its amount, oldest first, each as {@code <date> amount=<amount>}. */
    public record PlanView(long id, long personId, String amount, LocalDate start, Integer every, Integer day,
            LocalDate end, int generated, String nextDates, boolean paused, List<String> changes) {
        static PlanView of(Plan p, LocalDate today) {
            return new PlanView(p.getId(), p.getPersonId(),
                    p.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(), p.getStart(), p.getEvery(),
                    p.getDay(), p.getEnd(), p.getGenerated(),
                    p.nextDates(today, 5).stream().map(LocalDate::toString).collect(Collectors.joining(", ")),
                    p.isPaused(),
                    p.getChanges().stream().map(c -> c.getChangedOn() + " amount="
                            + c.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()).toList());
        }
    }

    /** A plan asked: its person, an amount (up to two decimals), a start and end (YYYY-MM-DD) and either an
     * interval in whole days or a day of the month (the other blank or absent). */
    public record PlanRequest(
            long personId,
            @NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String amount,
            @NotNull @Pattern(regexp = "\\s*\\d{4}-\\d{2}-\\d{2}\\s*") String start,
            @Pattern(regexp = "\\s*(\\d{1,5})?\\s*") String every,
            @Pattern(regexp = "\\s*(\\d{1,2})?\\s*") String day,
            @NotNull @Pattern(regexp = "\\s*\\d{4}-\\d{2}-\\d{2}\\s*") String end) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2);
        }

        Integer everyValue() {
            return whole(every);
        }

        Integer dayValue() {
            return whole(day);
        }

        private static Integer whole(String text) {
            return text == null || text.isBlank() ? null : Integer.valueOf(text.trim());
        }
    }

    /** A plan's new amount asked: above zero, with up to two decimals. */
    public record AmountRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String amount) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2);
        }
    }

    /** How many claims a generate made, the claims, and every plan on the sheet as it stands after. */
    public record GeneratedView(int made, List<ClaimView> claims, List<PlanView> plans) {
    }

    private final PlanService service;
    private final ClaimService claims;

    public PlanController(PlanService service, ClaimService claims) {
        this.service = service;
        this.claims = claims;
    }

    @GetMapping
    public List<PlanView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        String sheet = sheetId.trim();
        List<Plan> plans = service.plans(sheet);
        if (plans.isEmpty()) return List.of();
        LocalDate today = service.today(sheet);
        return plans.stream().map(p -> PlanView.of(p, today)).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PlanView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PlanRequest request) {
        String sheet = sheetId.trim();
        return PlanView.of(service.add(sheet, user.trim(), request.personId(), request.amountValue(),
                date(request.start()), request.everyValue(), request.dayValue(), date(request.end())),
                service.today(sheet));
    }

    @PostMapping("/{planId}/pause")
    public PlanView pause(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long planId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        String sheet = sheetId.trim();
        return PlanView.of(service.pause(sheet, user.trim(), planId), service.today(sheet));
    }

    @PostMapping("/{planId}/resume")
    public PlanView resume(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long planId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        String sheet = sheetId.trim();
        return PlanView.of(service.resume(sheet, user.trim(), planId), service.today(sheet));
    }

    @PostMapping("/{planId}/amount")
    public PlanView amount(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long planId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid AmountRequest request) {
        String sheet = sheetId.trim();
        return PlanView.of(service.changeAmount(sheet, user.trim(), planId, request.amountValue()),
                service.today(sheet));
    }

    @PostMapping("/generate")
    public GeneratedView generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        String sheet = sheetId.trim();
        List<ClaimView> made = ClaimView.allOf(service.generate(sheet, user.trim()), claims);
        return new GeneratedView(made.size(), made, list(sheet));
    }

    private static LocalDate date(String text) {
        try {
            return LocalDate.parse(text.trim());
        } catch (DateTimeParseException e) {
            throw new PlanDatesException();
        }
    }
}
